     2| * IVX Member Verification Service
     3| *
     4| * Generates verification codes, stores them in Supabase with TTL,
     5| * and provides verification endpoints for email and phone.
     6| * Email/SMS delivery is handled via the Rork AI gateway for now;
     7| * connect to SendGrid/Twilio for production.
     8| *
     9| * v2 (2026-07-03): The production Supabase schema is missing the
    10| * `verification_codes` table and the `profiles.email_verified` /
    11| * `profiles.phone_verified` columns (schema repair requires the
    12| * service-role key, which is not configured). All operations now
    13| * fall back to a resilient local store (durable store when
    14| * configured, filesystem otherwise) so verification works end to
    15| * end regardless of schema state. Supabase remains the primary
    16| * path and is used automatically once the schema exists.
    17| */
    18|
    19|import { createClient, type SupabaseClient } from '@supabase/supabase-js';
    20|import { readFile, writeFile, mkdir } from 'node:fs/promises';
    21|import path from 'node:path';
    22|import {
    23|  isDurableStoreConfigured,
    24|  readDurableJson,
    25|  writeDurableJson,
    26|} from './ivx-durable-store';
    27|
    28|const DEPLOYMENT_MARKER = 'ivx-member-verification-v2-fallback-store';
    29|const CODE_TTL_MINUTES = 10;
    30|const CODE_LENGTH = 6;
    31|const MAX_ATTEMPTS = 5;
    32|
    33|function getSupabaseAdmin(): SupabaseClient {
    34|  const url = process.env.SUPABASE_URL || process.env.EXPO_PUBLIC_SUPABASE_URL || '';
    35|  // Service-role key first; anon key as a working fallback (service key was rotated).
    36|  const key =
    37|    process.env.SUPABASE_SERVICE_ROLE_KEY ||
    38|    process.env.SUPABASE_SERVICE_KEY ||
    39|    process.env.SUPABASE_ANON_KEY ||
    40|    process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY ||
    41|    '';
    42|  return createClient(url, key, {
    43|    auth: { persistSession: false, autoRefreshToken: false },
    44|  });
    45|}
    46|
    47|function generateCode(): string {
    48|  let code = '';
    49|  for (let i = 0; i < CODE_LENGTH; i++) {
    50|    code += Math.floor(Math.random() * 10).toString();
    51|  }
    52|  return code;
