   109|async function fallbackStoreCode(input: StoreCodeInput, code: string, expiresAt: Date): Promise<void> {
   110|  const codes = await readStore<FallbackCodesStore>(CODES_FILE(), {});
   111|  codes[codeKey(input.userId, input.type)] = {
   112|    userId: input.userId,
   113|    type: input.type,
   114|    code,
   115|    attempts: 0,
   116|    expiresAt: expiresAt.toISOString(),
   117|    verifiedAt: null,
   118|    createdAt: new Date().toISOString(),
   119|  };
   120|  await writeStore(CODES_FILE(), codes);
   121|}
   122|
   123|async function fallbackMarkVerified(userId: string, type: 'email' | 'phone'): Promise<void> {
   124|  const statuses = await readStore<FallbackStatusStore>(STATUS_FILE(), {});
   125|  const current = statuses[userId] ?? { emailVerified: false, phoneVerified: false, updatedAt: '' };
   126|  statuses[userId] = {
   127|    emailVerified: type === 'email' ? true : current.emailVerified,
   128|    phoneVerified: type === 'phone' ? true : current.phoneVerified,
   129|    updatedAt: new Date().toISOString(),
   130|  };
   131|  await writeStore(STATUS_FILE(), statuses);
   132|}
