   134|async function fallbackVerifyCode(input: VerifyCodeInput): Promise<VerificationResult> {
   135|  const codes = await readStore<FallbackCodesStore>(CODES_FILE(), {});
   136|  const key = codeKey(input.userId, input.type);
   137|  const record = codes[key];
   138|
   139|  if (!record || record.verifiedAt) {
   140|    return {
   141|      success: false,
   142|      message: 'No pending verification found. Please request a new code.',
   143|      verified: false,
   144|      deploymentMarker: DEPLOYMENT_MARKER,
   145|    };
   146|  }
   147|
   148|  if (new Date(record.expiresAt) < new Date()) {
   149|    return {
   150|      success: false,
   151|      message: 'Verification code has expired. Please request a new code.',
   152|      verified: false,
   153|      deploymentMarker: DEPLOYMENT_MARKER,
   154|    };
   155|  }
   156|
   157|  if (record.attempts >= MAX_ATTEMPTS) {
   158|    return {
   159|      success: false,
   160|      message: 'Too many failed attempts. Please request a new code.',
   161|      verified: false,
   162|      deploymentMarker: DEPLOYMENT_MARKER,
   163|    };
   164|  }
   165|
   166|  record.attempts += 1;
   167|
   168|  if (record.code !== input.code) {
   169|    codes[key] = record;
   170|    await writeStore(CODES_FILE(), codes);
   171|    const remaining = MAX_ATTEMPTS - record.attempts;
   172|    return {
   173|      success: false,
   174|      message: `Invalid code. ${remaining} attempt${remaining !== 1 ? 's' : ''} remaining.`,
   175|      verified: false,
   176|      deploymentMarker: DEPLOYMENT_MARKER,
   177|    };
   178|  }
   179|
   180|  record.verifiedAt = new Date().toISOString();
   181|  codes[key] = record;
   182|  await writeStore(CODES_FILE(), codes);
   183|  await fallbackMarkVerified(input.userId, input.type);
   184|
   185|  // Best-effort: also try updating the Supabase profile (ignored if the
   186|  // columns do not exist yet).
   187|  try {
   188|    const supabase = getSupabaseAdmin();
   189|    const verifiedField = input.type === 'email' ? 'email_verified' : 'phone_verified';
   190|    await supabase
   191|      .from('profiles')
   192|      .update({ [verifiedField]: true, updated_at: record.verifiedAt })
   193|      .eq('id', input.userId);
   194|  } catch {
   195|    // non-critical
   196|  }
   197|
   198|  return {
   199|    success: true,
   200|    message: `${input.type === 'email' ? 'Email' : 'Phone'} verified successfully`,
   201|    verified: true,
   202|    deploymentMarker: DEPLOYMENT_MARKER,
   203|  };
   204|}
