   236|export async function storeVerificationCode(input: StoreCodeInput): Promise<VerificationResult> {
   237|  const supabase = getSupabaseAdmin();
   238|  const code = generateCode();
   239|  const now = new Date();
   240|  const expiresAt = new Date(now.getTime() + CODE_TTL_MINUTES * 60 * 1000);
   241|
   242|  try {
   243|    const { error } = await supabase.from('verification_codes').upsert(
   244|      {
   245|        user_id: input.userId,
   246|        type: input.type,
   247|        code,
   248|        attempts: 0,
   249|        expires_at: expiresAt.toISOString(),
   250|        verified_at: null,
   251|        created_at: now.toISOString(),
   252|      },
   253|      { onConflict: 'user_id,type' }
   254|    );
   255|
   256|    if (error) {
   257|      console.error('[MemberVerification] Supabase code store failed, using fallback store:', error.message);
   258|      await fallbackStoreCode(input, code, expiresAt);
   259|    } else {
   260|      console.log(`[MemberVerification] Code stored for ${input.userId} (${input.type})`);
   261|    }
   262|
   263|    return {
   264|      success: true,
   265|      message: `Verification code generated`,
   266|      verified: false,
   267|      code,
   268|      deploymentMarker: DEPLOYMENT_MARKER,
   269|    };
   270|  } catch (err) {
   271|    const message = err instanceof Error ? err.message : 'Unknown error';
   272|    console.error('[MemberVerification] Code store exception, using fallback store:', message);
   273|    try {
   274|      await fallbackStoreCode(input, code, expiresAt);
   275|      return {
   276|        success: true,
   277|        message: `Verification code generated`,
   278|        verified: false,
   279|        code,
   280|        deploymentMarker: DEPLOYMENT_MARKER,
   281|      };
