  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --gold: #FFD700;
      --gold-light: #FFF2A3;
      --gold-dim: rgba(255,215,0,0.1);
      --gold-border: rgba(255,215,0,0.22);
      --bg: #000000;
      --bg2: #141414;
      --surface: #1A1A1A;
      --surface2: #242424;
      --border: #2A2A2A;
      --text: #FFFFFF;
      --text2: #909090;
      --text3: #555555;
      --green: #00C48C;
      --red: #FF4D4D;
      --blue: #4A90D9;
    }

    html { scroll-behavior: auto; overflow-x: hidden; width: 100%; -webkit-text-size-adjust: 100%; text-size-adjust: 100%; }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      background: var(--bg);
      color: var(--text);
      overflow-x: hidden;
      -webkit-font-smoothing: antialiased;
      width: 100%;
      max-width: 100vw;
      /* overscroll-behavior-y: none; REMOVED — it blocked pull-to-refresh and made scroll-up feel stuck on mobile */
    }

    /* ─── LAYOUT-SHIFT DEFENSE (CLS) ─── */
    img, video, picture { max-width: 100%; display: block; }
    .media-frame { width: 100%; aspect-ratio: 16 / 10; overflow: hidden; position: relative; background: #111; }
    .media-frame img, .media-frame video { width: 100%; height: 100%; object-fit: cover; display: block; }
    .ivx-skeleton {
      position: absolute; inset: 0;
      background: linear-gradient(90deg, #141414 0%, #1f1f1f 50%, #141414 100%);
      background-size: 200% 100%;
      animation: ivxSkel 1.4s ease-in-out infinite;
      z-index: 1; pointer-events: none;
    }
    .ivx-skeleton.ivx-skel-hide { display: none; }
    @keyframes ivxSkel { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }

    /* ─── REELS CARDS (reserved space — no intrinsic-size jump) ─── */
    #vx-grid { display: grid; gap: 18px; grid-template-columns: 1fr; contain: layout style; }
    @media (min-width: 640px) { #vx-grid { grid-template-columns: repeat(2, 1fr); } }
    .vx-card { background: var(--surface); border: 1px solid var(--border); border-radius: 18px; overflow: hidden; contain: layout style; }
    .vx-media { position: relative; width: 100%; aspect-ratio: 9 / 16; max-height: 78vh; background: #000; overflow: hidden; }
    .vx-media video { width: 100%; height: 100%; object-fit: cover; display: block; background: #000; }
    .vx-play-overlay, .vx-heart-burst, .vx-mute-btn { z-index: 6; }
    .vx-head, .vx-actions, .vx-likes-line, .vx-caption, .vx-viewall, .vx-comments, .vx-time, .vx-comment-form { contain: content; }

    /* ─── NAV ─── */
    nav {
      position: fixed;
      top: 0; left: 0; right: 0;
      z-index: 200;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 40px;
      height: 68px;
      background: rgba(10,10,10,0.88);
      backdrop-filter: blur(24px);
      -webkit-backdrop-filter: blur(24px);
      border-bottom: 1px solid var(--border);
      transition: background 0.3s;
    }
    .nav-logo {
      display: flex; align-items: center; gap: 10px;
      text-decoration: none;
    }
    .nav-logo-icon {
      width: 40px; height: 40px;
      flex-shrink: 0;
      display: flex; align-items: center; justify-content: center;
      border-radius: 10px;
      overflow: hidden;
    }
    .nav-logo-icon img {
      width: 40px; height: 40px;
      object-fit: contain;
      display: block;
    }
    .nav-logo-name {
      font-size: 14px; font-weight: 800;
      letter-spacing: 1.8px; color: var(--text);
    }
    .nav-links {
      display: flex; align-items: center; gap: 32px; list-style: none;
    }
    .nav-links a {
      color: var(--text2); text-decoration: none;
      font-size: 13.5px; font-weight: 500;
      transition: color 0.2s;
    }
    .nav-links a:hover { color: var(--text); }
    .nav-cta-btn {
      background: var(--gold) !important;
      color: #000 !important;
      font-weight: 700 !important;
      padding: 9px 20px;
      border-radius: 10px;
      transition: background 0.2s, transform 0.15s !important;
    }
    .nav-cta-btn:hover { background: var(--gold-light) !important; transform: translateY(-1px); }
    .nav-reels-btn {
      display: flex; align-items: center; justify-content: center;
      width: 42px; height: 42px; flex-shrink: 0;
      margin-left: 16px;
      border-radius: 12px;
      background: rgba(230,194,0,0.12);
      border: 1px solid rgba(230,194,0,0.4);
      color: #E6C200;
      cursor: pointer;
      transition: background 0.2s, transform 0.15s;
      touch-action: manipulation;
      -webkit-tap-highlight-color: transparent;
    }
    .nav-reels-btn:hover { background: rgba(230,194,0,0.24); transform: translateY(-1px); }
    .nav-reels-btn:active { transform: scale(0.94); }
    .nav-reels-btn svg { display: block; }
    .nav-hamburger {
      display: none; cursor: pointer; flex-direction: column; gap: 5px; padding: 4px;
      position: relative;
      z-index: 260;
      touch-action: manipulation;
      -webkit-tap-highlight-color: transparent;
    }
    .live-deal-actions button {
      touch-action: manipulation;
      -webkit-tap-highlight-color: transparent;
      position: relative;
      z-index: 3;
    }
    .nav-hamburger span {
      display: block; width: 22px; height: 2px;
      background: var(--text2); border-radius: 2px;
      transition: transform 0.25s ease, opacity 0.25s ease;
    }
    @media(max-width: 800px) {
      nav { padding: 0 20px; }
      .nav-links:not(.mobile-open) { display: none; }
      .nav-hamburger { display: flex; }
      .nav-links.mobile-open {
        display: flex !important;
        flex-direction: column;
        position: fixed;
        top: 68px; left: 0; right: 0;
        background: rgba(17,17,17,0.98);
        backdrop-filter: blur(20px);
        -webkit-backdrop-filter: blur(20px);
        padding: 20px 24px 28px;
        border-bottom: 1px solid var(--border);
        z-index: 199;
        gap: 18px;
        animation: mobilemenu 0.25s ease both;
      }
      .nav-links.mobile-open .nav-cta-btn {
        text-align: center;
        width: 100%;
        justify-content: center;
      }
    }
    @keyframes mobilemenu {
      from { opacity: 0; transform: translateY(-10px); }
      to   { opacity: 1; transform: translateY(0); }
    }

    /* ─── LIVE ACTIVITY TICKER ─── */
    .live-ticker-bar {
      position: fixed;
      top: 68px; left: 0; right: 0;
      z-index: 190;
      background: rgba(0,30,18,0.92);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-bottom: 1px solid rgba(0,196,140,0.15);
      padding: 9px 20px;
      display: none;
      align-items: center;
      gap: 10px;
      overflow: hidden;
      height: 38px;
    }
    .live-ticker-bar.visible {
      display: flex;
    }
    .live-ticker-dot {
      width: 8px; height: 8px; border-radius: 50%;
      background: var(--green);
      animation: glow-pulse 1.8s infinite;
      flex-shrink: 0;
    }
    .live-ticker-text {
      flex: 1;
      font-size: 12px;
      color: #9A9A9A;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
      transition: opacity 0.3s, transform 0.3s;
    }
    .live-ticker-text strong { color: #fff; font-weight: 700; }
    .live-ticker-text .ticker-loc { color: #5A5A5A; }
    .live-ticker-time {
      font-size: 10px;
      color: #4A4A4A;
      flex-shrink: 0;
    }

    /* ─── HERO ─── */
    .hero {
      min-height: 100vh;
      padding: 106px 16px 80px;
      display: flex; flex-direction: column;
      align-items: center; justify-content: center;
      position: relative; overflow: hidden;
      width: 100%;
    }
    @media(min-width: 600px) { .hero { padding: 106px 24px 100px; } }
    .hero-bg-glow {
      position: absolute; inset: 0; pointer-events: none;
      background:
        radial-gradient(ellipse 80% 60% at 50% 0%, rgba(255,215,0,0.07) 0%, transparent 65%),
        radial-gradient(ellipse 50% 50% at 85% 85%, rgba(0,196,140,0.04) 0%, transparent 55%);
    }
    .hero-grid-lines {
      position: absolute; inset: 0; pointer-events: none;
      background-image:
        linear-gradient(rgba(255,215,0,0.035) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255,215,0,0.035) 1px, transparent 1px);
      background-size: 64px 64px;
      mask-image: radial-gradient(ellipse 75% 55% at 50% 50%, black 30%, transparent);
    }
    .hero-inner {
      position: relative; z-index: 2;
      max-width: 860px; width: 100%;
      text-align: center;
      overflow: hidden;
    }
    .hero-badge {
      display: inline-flex; align-items: center; gap: 8px;
      background: var(--gold-dim);
      border: 1px solid var(--gold-border);
      border-radius: 100px;
      padding: 7px 16px;
      font-size: 10.5px; font-weight: 700;
